package com.example.customerrouting.routing; import com.example.customerrouting.skill.Skill; import org.springframework.stereotype.*; import java.util.*; @Component public class SkillMatcher { public double containment(Set<String> required,Collection<Skill> actual){ if(required==null||required.isEmpty()) return 0d; Set<String> codes=new HashSet<>(); actual.forEach(s->codes.add(s.getCode())); return (double)required.stream().filter(codes::contains).count()/required.size(); } public boolean qualifies(double score){return score>=.80d;} }
